#include <iostream>
#include <vector>
using namespace std;
​
int main() {
    // 处理输入
    int productNumber, days;
    cin >> productNumber >> days;
​
    vector<int> maxItems(productNumber); 
    for (int i = 0; i < productNumber; i++) {
        cin >> maxItems[i];
    }
​
    vector<vector<int>> prices(productNumber, vector<int>(days)); // 商品价格列表
    for (int i = 0; i < productNumber; i++) {
        for (int j = 0; j < days; j++) {
            cin >> prices[i][j];
        }
    }
​
    // 贪心算法
    int maxProfit = 0;
    for (int i = 0; i < productNumber; i++) { // 遍历每件商品
        for (int j = 1; j < days; j++) { 
            // 当前价格减去前一天价格，如果为负数则代表亏本，不计入利润
            int profit = max(0, prices[i][j] - prices[i][j - 1]);

            maxProfit += profit * maxItems[i]; 
        }
    }
​
    cout << maxProfit << endl;
    return 0;
}
