import java.util.Scanner;
​
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // 处理输入
        int productNumber = sc.nextInt();
        int days = sc.nextInt();

        int[] maxItems = new int[productNumber];
        for (int i = 0; i < productNumber; i++) {
            maxItems[i] = sc.nextInt();
        }

        int[][] prices = new int[productNumber][days]; // 商品价格列表
        for (int i = 0; i < productNumber; i++) {
            for (int j = 0; j < days; j++) {
                prices[i][j] = sc.nextInt();
            }
        }

        // 贪心算法
        int maxProfit = 0;
        for (int i = 0; i < productNumber; i++) { // 遍历每件商品
            for (int j = 1; j < days; j++) {
                // 当前价格减去前一天价格，如果为负数则代表亏本，不计入利润
                int profit = Math.max(0, prices[i][j] - prices[i][j - 1]);
                maxProfit += profit * maxItems[i];
            }
        }

        System.out.println(maxProfit);
    }
}
