const readline = require('readline');
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});
​
// 读取第一行：商品数量
rl.question('', (line) => {
  const productNumber = parseInt(line);  // 商品数量
​
  // 读取第二行：天数
  rl.question('', (line) => {
    const days = parseInt(line);  // 天数
​
    // 读取第三行：每个商品的最大购买量
    rl.question('', (line) => {
      const maxItems = line.split(' ').map(Number);
​
      // 读取后续的价格数据
      let prices = [];
      let count = 0;
​
      rl.on('line', (line) => {
        prices.push(line.split(' ').map(Number));
        count++;
​
        // 完成所有输入后开始计算
        if (count === productNumber) {
          let maxProfit = 0;
​
          for (let i = 0; i < productNumber; i++) { // 遍历每件商品
            for (let j = 1; j < days; j++) {
              // 当前价格减去前一天价格，如果为负数则代表亏本，不计入利润
              let profit = Math.max(0, prices[i][j] - prices[i][j - 1]);
              maxProfit += profit * maxItems[i];
            }
          }
​
          console.log(maxProfit);  // 输出最大利润
          rl.close();
        }
      });
    });
  });
});
