package main
​
import (
    "fmt"
    "math"
)
​
func main() {
    // 处理输入
    var productNumber, days int
    fmt.Scan(&productNumber, &days)
​
    maxItems := make([]int, productNumber)
    for i := 0; i < productNumber; i++ {
        fmt.Scan(&maxItems[i])
    }
​
    prices := make([][]int, productNumber) // 商品价格列表
    for i := 0; i < productNumber; i++ {
        prices[i] = make([]int, days)
        for j := 0; j < days; j++ {
            fmt.Scan(&prices[i][j])
        }
    }
​
    // 贪心算法
    maxProfit := 0
    for i := 0; i < productNumber; i++ { // 遍历每件商品
        for j := 1; j < days; j++ {
            // 当前价格减去前一天价格，如果为负数则代表亏本，不计入利润
            profit := int(math.Max(float64(0), float64(prices[i][j]-prices[i][j-1])))
            maxProfit += profit * maxItems[i]
        }
    }
​
    fmt.Println(maxProfit)
}
